import { Chat, type ChatSendDetail } from '@absoluteui/components/chat';

const host = document.createElement('div');
document.body.append(host);
const chat = Chat.create(host, { label: 'Conversation with the assistant', suggestions: [{ id: 'leave', label: 'How many leave days do I have?' }] });

// Any async iterable of text chunks works: here a generator that waits between words.
async function* reply(text: string, signal: AbortSignal): AsyncGenerator<string> {
  for (const word of text.split(' ')) {
    await new Promise((resolve) => setTimeout(resolve, 60));
    if (signal.aborted) return;
    yield `${word} `;
  }
}

host.addEventListener('aui-send', (event) => {
  const { text } = (event as CustomEvent<ChatSendDetail>).detail;
  void chat.stream((signal) => reply(`You asked: **${text}**. Here is what I found.`, signal));
});

import { Chat, type ChatSendDetail, type ChatRetryDetail } from '@absoluteui/components/chat';

const host = document.createElement('div');
document.body.append(host);
const chat = Chat.create(host, { label: 'Assistant' });

function ask(question: string, id?: string): void {
  void chat.stream(async function* (signal) {
    // Stop aborts the request too.
    const response = await fetch('/api/answer', { method: 'POST', body: JSON.stringify({ question }), signal });
    if (!response.ok || !response.body) throw new Error(String(response.status));
    const reader = response.body.pipeThrough(new TextDecoderStream()).getReader();
    for (;;) {
      const { done, value } = await reader.read();
      if (done) return;
      yield value;
    }
  }, id === undefined ? {} : { id });
}

host.addEventListener('aui-send', (event) => {
  ask((event as CustomEvent<ChatSendDetail>).detail.text);
});
host.addEventListener('aui-retry', (event) => {
  const { id, prompt } = (event as CustomEvent<ChatRetryDetail>).detail;
  if (prompt) ask(prompt.text, id);
});

import { instant } from '@absoluteui/core';
import { Chat } from '@absoluteui/components/chat';

const host = document.createElement('div');
document.body.append(host);
const chat = Chat.create(host, {
  label: 'Chat with Grace Hopper',
  authors: { assistant: { name: 'Grace Hopper' } },
  assistantFormat: 'text',
  feedback: false,
  messages: [
    { id: '1', role: 'assistant', text: 'Did you get the onboarding checklist?', timestamp: instant(Date.UTC(2026, 10, 20, 9, 30)) },
    { id: '2', role: 'user', text: 'Yes, thank you. One question about the laptop.', timestamp: instant(Date.UTC(2026, 10, 20, 9, 32)) },
  ],
});
chat.update({ typing: 'Grace Hopper' });

import { instant, plainDate } from '@absoluteui/core';
import { createBusinessCalendar } from '@absoluteui/components/business-calendar';
import { Chat } from '@absoluteui/components/chat';

const calendar = createBusinessCalendar({ holidays: [{ date: plainDate(2026, 12, 25), name: 'Christmas Day', yearly: true }] });
const host = document.createElement('div');
document.body.append(host);
Chat.create(host, {
  label: 'Support conversation',
  businessCalendar: calendar,
  timezone: 'Europe/London',
  messages: [{ id: '1', role: 'user', text: 'Is anyone working today?', timestamp: instant(Date.UTC(2026, 11, 25, 10)) }],
});
